-- Generated by `make contracts` from contracts/cdc_haicviz_cdi.odcs.yaml. Do not edit: change the contract and regenerate.
-- Types the latest raw load only; every business rule lives in intermediate models.
with raw as (
    select * from {{ source('raw', 'cdc_haicviz_cdi') }}
),

latest as (
    select * from raw where filename = (select max(filename) from raw)
)

select
  CASE WHEN CAST(NULLIF(trim("yearname"), '') AS DECIMAL(38, 6)) IS NULL THEN NULL WHEN CAST(NULLIF(trim("yearname"), '') AS DECIMAL(38, 6)) = trunc(CAST(NULLIF(trim("yearname"), '') AS DECIMAL(38, 6))) THEN CAST(CAST(NULLIF(trim("yearname"), '') AS DECIMAL(38, 6)) AS BIGINT) ELSE error('yearname: a value has a fraction, so it isn''t a whole count; check the contract') END AS "yearname",
  "topic" AS "topic",
  "viewby" AS "viewby",
  "grouping" AS "grouping",
  "series" AS "series",
  CAST(NULLIF(trim("value"), '') AS DOUBLE) AS "value"
from latest
